// --- FR-N8N-01 & FR-SRK-03: Validasi & Sanitasi Data Srikandi ---
const body = $input.first().json.body || $input.first().json;

if (!body || !body.dokumen) {
  throw new Error('Payload Srikandi tidak valid: atribut dokumen tidak ditemukan.');
}

const doc = body.dokumen;
const status = (body.status || 'surat_baru').toLowerCase().trim();
const sifat = (doc.sifat || 'Biasa').trim();

// Format Tanggal Indonesia (DD MMMM YYYY)
function formatTanggalIndo(tglStr) {
  if (!tglStr) return '-';
  const bulanIndo = [
    'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
    'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'
  ];
  const d = new Date(tglStr);
  if (isNaN(d.getTime())) return tglStr;
  return `${d.getDate()} ${bulanIndo[d.getMonth()]} ${d.getFullYear()}`;
}

// Sanitasi teks
function cleanText(str, maxLength = 120) {
  if (!str) return '-';
  let cleaned = str.replace(/\s+/g, ' ').trim();
  if (cleaned.length > maxLength) {
    cleaned = cleaned.substring(0, maxLength - 3) + '...';
  }
  return cleaned;
}

// Kebijakan Dokumen Rahasia (FR-SRK-04)
let sanitizedPerihal = cleanText(doc.perihal, 120);
if (sifat.toLowerCase().includes('rahasia')) {
  sanitizedPerihal = '[DOKUMEN BERSIFAT RAHASIA / KONFIDENSIAL]';
}

// Ekstraksi Variabel Pesan Terstruktur (FR-N8N-04)
const outputData = {
  event_type: body.event_type || 'notifikasi_dokumen',
  status: status,
  nomor_surat: (doc.nomor_surat || '-').replace(/\s+/g, ' ').trim(),
  tanggal: formatTanggalIndo(doc.tanggal_surat),
  asal: cleanText(doc.asal_pengirim || 'Instansi Terkait', 80),
  perihal: sanitizedPerihal,
  sifat: sifat,
  penerima_nip: doc.penerima_nip || '',
  penerima_nama: doc.penerima_nama || 'Pegawai BRIDA',
  pemberi_disposisi: cleanText(doc.pemberi_disposisi || 'Pimpinan BRIDA', 60),
  instruksi_disposisi: cleanText(doc.instruksi_disposisi || '-', 100),
  catatan_verifikasi: cleanText(doc.catatan_verifikasi || doc.status_verifikasi || '-', 100),
  deduplication_key: `${(doc.nomor_surat || 'NODOC').trim()}_${status}`
};

return [{ json: outputData }];

// FR-WA-01: Template Surat Baru
const d = $input.first().json;
const pesan = `*🔔 [SIGAP BRIDA] Surat Masuk Baru*

Yth. Bpk/Ibu *${d.penerima_nama}*,
Terdapat surat masuk baru pada aplikasi Srikandi:

📄 *No. Surat* : ${d.nomor_surat}
🏢 *Dari*       : ${d.asal}
📌 *Perihal*   : ${d.perihal}
📅 *Tanggal*   : ${d.tanggal}
🔒 *Sifat*     : ${d.sifat}

Silakan masuk ke aplikasi Srikandi untuk membaca naskah dinas lengkap.

_Pesan otomatis dari Sistem Informasi SIGAP BRIDA Kota Makassar_`;

return [{ json: { ...d, rendered_message: pesan } }];

// FR-WA-02: Template Disposisi Pimpinan
const d = $input.first().json;
const pesan = `*⚡ [SIGAP BRIDA] Disposisi Dokumen*

Yth. Bpk/Ibu *${d.penerima_nama}*,
Anda menerima disposisi baru pada aplikasi Srikandi:

📄 *No. Surat* : ${d.nomor_surat}
👤 *Dari*       : ${d.pemberi_disposisi}
📌 *Perihal*   : ${d.perihal}
📝 *Instruksi* : ${d.instruksi_disposisi}
📅 *Tanggal*   : ${d.tanggal}

Mohon segera menindaklanjuti instruksi tersebut di Srikandi.

_Pesan otomatis dari Sistem Informasi SIGAP BRIDA Kota Makassar_`;

return [{ json: { ...d, rendered_message: pesan } }];

// FR-WA-03: Template Verifikasi Dokumen
const d = $input.first().json;
const pesan = `*📋 [SIGAP BRIDA] Verifikasi Naskah Dinas*

Yth. Bpk/Ibu *${d.penerima_nama}*,
Naskah dinas memerlukan perhatian/tindakan verifikasi Anda:

📄 *No. Surat* : ${d.nomor_surat}
🏢 *Unit Pengirim* : ${d.asal}
📌 *Perihal*   : ${d.perihal}
🔍 *Catatan*   : ${d.catatan_verifikasi}
📅 *Tanggal*   : ${d.tanggal}

Silakan cek modul verifikasi pada aplikasi Srikandi.

_Pesan otomatis dari Sistem Informasi SIGAP BRIDA Kota Makassar_`;

return [{ json: { ...d, rendered_message: pesan } }];

// Fallback untuk status tidak dikenal (FR-WA-04)
const d = $input.first().json;
const pesan = `*ℹ️ [SIGAP BRIDA] Pembaruan Dokumen*

Yth. Bpk/Ibu *${d.penerima_nama}*,
Terdapat pembaruan status (${d.status}) untuk surat no: ${d.nomor_surat}.
Silakan periksa di aplikasi Srikandi.

_SIGAP BRIDA Kota Makassar_`;

return [{ json: { ...d, rendered_message: pesan } }];

// FR-N8N-07: Pemetaan Nomor WhatsApp Penerima
const item = $input.first().json;

// Nomor fallback jika NIP tidak ditemukan
const defaultPhone = '6281234567890';

// Kamus nomor pegawai BRIDA (dapat dipindah ke basis data / environment variable)
const phoneBook = {
  '198501152010011012': '6281234567890',
  '197803202005021004': '6281398765432',
  '199205122019032007': '6282111223344'
};

const targetPhone = phoneBook[item.penerima_nip] || defaultPhone;

return [{
  json: {
    chatId: `${targetPhone}@c.us`,
    text: item.rendered_message,
    session: 'default',
    metadata: {
      nomor_surat: item.nomor_surat,
      status: item.status,
      deduplication_key: item.deduplication_key
    }
  }
}];
